select p.date, p.open, p.high, p.low, p.close, p.volume, f.sma_20, f.sma_50, f.ema_12, f.ema_26, f.ema_50, f.ema_200, f.rsi_14, f.macd, f.macd_signal, f.atr_14, f.bb_upper_20, f.bb_middle_20, f.bb_lower_20, f.adx_14 from public."Price_Stock_Indonesia_IDX" p left join public."Feature_04_Technical_Indicator" f on f.ticker=p.ticker and f.trade_date=p.date and f.asset_type='equity' where p.ticker='BNBR' and p.is_final and p.timeframe='Daily' order by p.date
